-- Hyprland config (Lua format, 0.55+).
-- Wiki: https://wiki.hypr.land/Configuring/Start/
--
-- This file is machine-agnostic. Anything specific to a machine class
-- (pc vs laptop) lives in machine/, anything specific to one box (monitor
-- layout, GPU pinning, per-box autostart) lives in hosts/.
--
-- install.sh generates local.lua, which selects both. See local.lua.example.

------------------------
---- LOCAL SELECTOR ----
------------------------

-- local.lua is generated by install.sh and is NOT tracked in git.
-- Fall back to a sane default so a missing local.lua never breaks the session.
local ok, localcfg = pcall(require, "local")
if not ok then
    localcfg = { machine = "pc", host = nil }
end

------------------------
---- MY PROGRAMS -------
------------------------

local terminal    = "kitty"
local fileManager = "dolphin"
local launcher    = "hyprlauncher -t" -- toggle against the daemon started in autostart

-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORMTHEME", "kde")
hl.env("SAL_USE_VCLPLUGIN", "kf6")
hl.env("XDG_MENU_PREFIX", "arch-")

